<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {Button,Input} from '@openclaw-plugins/control-ui-kit';
import {buildKnowledgeTree,flattenKnowledgeTree,type KnowledgeTreeRow} from './knowledge-tree';
import type {KnowledgeEntry} from './knowledge-model';
const props=defineProps<{entries:KnowledgeEntry[];selected:string;redact:(v:unknown)=>string}>(),emit=defineEmits<{select:[path:string]}>();
const opened=ref(new Set<string>()),filter=ref(''),scroll=ref(0),box=ref<HTMLElement>();
watch(()=>props.selected,p=>{const parts=p.split('/');for(let i=1;i<parts.length;i++)opened.value.add(parts.slice(0,i).join('/'));},{immediate:true});
const tree=computed(()=>buildKnowledgeTree(props.entries)),rows=computed(()=>flattenKnowledgeTree(tree.value,opened.value,filter.value));
const rowHeight=38,start=computed(()=>Math.max(0,Math.floor(scroll.value/rowHeight)-5)),slice=computed(()=>rows.value.slice(start.value,start.value+28));
watch(filter,()=>{scroll.value=0;if(box.value)box.value.scrollTop=0;});
watch([()=>props.selected,tree],()=>{const i=rows.value.findIndex(r=>r.entry?.path===props.selected);if(i>=0&&box.value){box.value.scrollTop=i*rowHeight;scroll.value=box.value.scrollTop;}},{flush:'post'});
function toggle(row:KnowledgeTreeRow){if(opened.value.has(row.path))opened.value.delete(row.path);else opened.value.add(row.path);}
function choose(row:KnowledgeTreeRow){if(row.entry){if(row.folder)opened.value.add(row.path);emit('select',row.entry.path);}else toggle(row);}
</script>
<template><nav aria-label="知识目录树" class="kb-tree"><Input v-model="filter" aria-label="筛选目录树" placeholder="查找知识标题或路径"/><div ref="box" class="kb-tree-scroll" @scroll="scroll=($event.target as HTMLElement).scrollTop"><div :style="{height:rows.length*rowHeight+'px',position:'relative'}"><div v-for="(row,i) in slice" :key="row.path" class="kb-tree-row" :class="{'is-current':selected===row.entry?.path}" :style="{top:(start+i)*rowHeight+'px',paddingLeft:(row.depth*14)+'px'}"><Button v-if="row.folder" variant="ghost" size="icon" class="kb-tree-toggle" :disabled="!!filter.trim()" :aria-label="((filter.trim()||opened.has(row.path))?'收起':'展开')+' '+redact(row.title)" :aria-expanded="!!filter.trim()||opened.has(row.path)" @click="toggle(row)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true" :class="{expanded:!!filter.trim()||opened.has(row.path)}"><path d="m9 5 7 7-7 7"/></svg></Button><span v-else class="kb-tree-toggle"/><Button variant="ghost" size="sm" class="kb-tree-label" :aria-current="selected===row.entry?.path?'page':undefined" :aria-expanded="row.folder&&!row.entry?(!!filter.trim()||opened.has(row.path)):undefined" :title="redact(row.entry?.path??row.path)" @click="choose(row)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path :d="row.folder?'M3 7h7l2 2h9v11H3Z M3 7V4h7l2 3':'M6 3h8l4 4v14H6Z M14 3v5h4 M9 12h6 M9 16h6'"/></svg><span>{{redact(row.title)}}</span></Button></div></div></div><small>{{entries.length}} 篇文档<span v-if="filter&&!rows.length"> · 没有匹配的知识</span></small></nav></template>
<style scoped>.kb-tree{min-width:0;padding:12px;border:1px solid var(--ocp-border);border-radius:10px}.kb-tree-scroll{height:560px;overflow:auto;margin-top:8px}.kb-tree-row{position:absolute;height:38px;width:100%;display:flex;align-items:center;border-radius:6px;box-sizing:border-box}.kb-tree-row.is-current{background:var(--ocp-muted-background);color:var(--ocp-primary)}.kb-tree-toggle{width:28px;height:32px;flex:none;padding:6px}.kb-tree-toggle svg{width:14px;height:14px;transition:transform .15s}.kb-tree-toggle svg.expanded{transform:rotate(90deg)}.kb-tree-label{min-width:0;flex:1;height:34px;justify-content:flex-start;padding:6px;gap:8px;font-weight:400}.kb-tree-label svg{width:16px;height:16px;flex:none;opacity:.7}.kb-tree-label span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.kb-tree-label[aria-current=page]{font-weight:600}small{color:var(--ocp-muted);font-size:12px}@media(prefers-reduced-motion:reduce){.kb-tree-toggle svg{transition:none}}</style>
